window.SAQ_PAPER_QUESTIONS["2024-1-st-george"]=[{"number":1,"title":"","stemText":"A 42-year-old man presents to ED with a 4-day history of shortness of breath on exertion, and a cough productive of white sputum. He has no other background history.\nHis blood pressure is 85/50, pulse 120 regular, oxygen saturation on room air is 93%.\nHis ECG is shown below :","parts":[{"id":"a","label":"Part A","prompt":"Give (3) salient findings seen in the ECG (3 marks) 1. 2. 3. You perform a point-of-care cardiac ultrasound on the patient. Below is a parasternal log axis view of his heart, paused at the closing and opening of the mitral valve :"},{"id":"b","label":"Part B","prompt":"List (3) important findings on the ultrasound. (3 marks) 1. 2. 3. You go on to do further cardiac views and a lung ultrasound :"},{"id":"c","label":"Part C","prompt":"State (3) further findings on these images. (3 marks) 1. 2. 3."},{"id":"d","label":"Part D","prompt":"What is the MOST LIKELY diagnosis? Give (2) possible causes of this diagnosis in any patient. (3 marks) Diagnosis\nCause 1\nCause 2"}],"propPages":["asset:imgd5c1a911eeb0e8349a","asset:img794dc699e6f0908d7e","asset:img173280c8092774a822","asset:imgbe6d199ddac713fd71","asset:imgdd93c6490ebd2eb699","asset:img587caa913b98ad2051"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Sinus tachycardia</div><div class=\"answer-line\">• Poor R wave progression</div><div class=\"answer-line\">• Biphasic P wave in V1</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Dilated LA</div><div class=\"answer-line\">• Poor EPPS (e point septal separaƟon) – indicaƟng poor LV funcƟon</div><div class=\"answer-line\">• Pleural eﬀusion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Ballooning of LV on A4C view</div><div class=\"answer-line\">• DilaƟon of IVC with poor respiratory variaƟon</div><div class=\"answer-line\">• MulƟple B lines indicaƟng likely pulmonary oedema.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Dilated cardiomyopathy<strong> </strong></div><div class=\"answer-line\">Causes</div><div class=\"answer-line\">• Viral cardiomyopathy</div><div class=\"answer-line\">• Alcoholic cardiomyopathy</div><div class=\"answer-line\">• Post partum cardiomyopathy</div><div class=\"answer-line\">• MedicaƟons (eg chemotherapy)</div><div class=\"answer-line\">• Hypertension</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 5-day-old male who was discharged 48 hours ago from the post-natal ward has been\nbrought in by his mother for poor feeding and lethargy. He is exclusively breasƞed. In the last 24hrs, he has been falling asleep at the breast before completing a feed and needs to\n\nbe woken up for feeds every 3 hours.\nBaby was born at term without significant antenatal concerns and no admission to special care nursery.\nHis vital signs are as follows: HR 145, RR 35, sats 96% on RA, cap refill 2 seconds, temp\n37.0, BSL 4.1 Birth weight: 3400g Current weight: 3200g","parts":[{"id":"a","label":"Part A","prompt":"Outline (5) causes of poor feeding in ANY neonate (5 marks) 1. 2. 3. 4. 5."},{"id":"b","label":"Part B","prompt":"At what weight threshold would weight loss in a neonate be a clinical concern? (1 mark) On examination you notice moderate scleral icterus and yellowing of the skin to the head and torso."},{"id":"c","label":"Part C","prompt":"List, with justification, (4) investigations you would consider as part of the work-up for neonatal jaundice. (4 marks) Investigation Justification The serum bilirubin returns at 200umol/L, which is marginally under the phototherapy threshold on the bilirubin nomogram chart. The other investigations are also reassuring for a benign cause of jaundice, namely mild dehydration."},{"id":"d","label":"Part D","prompt":"How would you safety-net this baby and his mother on discharge? (2 marks - 1⁄2 mark each) 1. 2. 3. 4."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• InfecƟve, eg sepsis, bronchioliƟs, meningiƟs</div><div class=\"answer-line\">• Anatomical, eg cleŌ palate, tongue Ɵe</div><div class=\"answer-line\">• Cardiorespiratory eg congenital heart disease, hyaline membrane disease</div><div class=\"answer-line\">• Gastro-oesophageal reﬂux disease</div><div class=\"answer-line\">• Lethargy secondary to hypoglycaemia</div><div class=\"answer-line\">• (Lethargy secondary to hyperbilirubinaemia)</div><div class=\"answer-line\">• Inborn error of metabolism</div><div class=\"answer-line\">• Maternal: poor milk supply, inverted nipples, excessive vomiƟng from rapid milk</div><div class=\"answer-line\">letdown</div><div class=\"answer-line\">• Cow’s milk protein intolerance if formula or maternal exposure to dairy</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• More than 10% weight loss from birth weight</div><div class=\"answer-line\">• Failure to regain birth weight by age 14 days</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Serum bilirubin (SBR) – determinaƟon of treatment threshold for phototherapy</div><div class=\"answer-line\">• FBC – idenƟfy potenƟal haemolysis</div><div class=\"answer-line\">• LFT – idenƟfy paterns of obstrucƟve jaundice</div><div class=\"answer-line\">• Group and DAT – haemolysis screen - seek and treat HBO incompaƟbility</div><div class=\"answer-line\">• G6PD – haemolysis screen especially in males, Asian / Middle Eastern / African</div><div class=\"answer-line\">descent</div><div class=\"answer-line\">• Inﬂammatory markers eg WCC, CRP – risk straƟfy for sepsis as cause</div><div class=\"answer-line\">• Blood ﬁlm – if low Hb or high clinical suspicion for haemolysis</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Feeding plan including formula top-ups to breasƞeeding</div><div class=\"answer-line\">• Referral to lactaƟon consultant</div><div class=\"answer-line\">• Repeat SBR in 24hrs to ensure improving</div><div class=\"answer-line\">• Referral to GP</div><div class=\"answer-line\">• Discuss red ﬂags for representaƟon</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A nurse has asked you to check position of this NGT on CXR, inserted by one of your medical students :","parts":[{"id":"a","label":"Part A","prompt":"List (3) relevant findings on this image. (3 marks) 1. 2. 3."},{"id":"b","label":"Part B","prompt":"Outline (3) immediate clinical actions you would take. (3 marks) 1. 2. 3."},{"id":"c","label":"Part C","prompt":"Briefly outline (6) steps you would take in managing this incident. (6 marks) 1. 2. 3. 4. 5. 6."}],"propPages":["asset:imgd6cd074a13b9fbbcbd"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>1. </strong>NGT has gone down R main bronchus</div><div class=\"answer-line\"><strong>2. </strong>Iatrogenic R-sided pneumothorax</div><div class=\"answer-line\"><strong>3. </strong>R basal opacification – unlikely to be fluid as would expect horizontal air-fluid</div><div class=\"answer-line\">interface</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>1. </strong>Immediate removal of misplaced NGT</div><div class=\"answer-line\"><strong>2. </strong>Supportive : ensure patient clinically stable, provide oxygen and analgesia</div><div class=\"answer-line\"><strong>3. </strong>Insert R small-bore ICC to treat iatrogenic injury<strong> </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>1. Open disclosure</strong> of event to patient / relatives</div><div class=\"answer-line\"><strong>2. Document</strong> the incident and discussion with patient</div><div class=\"answer-line\"><strong>3. Notify incident</strong> via hospital’s Incident Management Database</div><div class=\"answer-line\"><strong>4. Counsel / debrief</strong> the student and the supervising RN / MO</div><div class=\"answer-line\"><strong>5. </strong>Notify student’s clinical supervisor and review policy/procedure for clinical</div><div class=\"answer-line\">supervision of medical students</div><div class=\"answer-line\"><strong>6. </strong>Refer for review and education via M+M</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 64-year-old man with a history of end-stage renal failure presents 1 hour aŌer home\nhaemodialysis with bleeding from his AV fistula site. A towel wrapped around the arm is soaked through with blood. Past medical history also includes HTN, diabetes and IHD. He appears pale and distressed with the following obs :\n\nT 37.8 HR 110 BP 95/60 RR 24 Sats 95% RA","parts":[{"id":"a","label":"Part A","prompt":"What are (4) factors which might contribute to haemorrhage in this patient? (4 marks) 1. 2. 3. 4."},{"id":"b","label":"Part B","prompt":"List and describe (4) interventions you might undertake to control the bleeding, including drugs and doses where relevant. (8 marks) Intervention Details"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• SupratherapeuƟc anƟcoagulaƟon</div><div class=\"answer-line\">• InfecƟon</div><div class=\"answer-line\">• Stenosis</div><div class=\"answer-line\">• Aneurysm/pseudoaneurysm</div><div class=\"answer-line\">• Platelet dysfuncƟon from uraemia/TTP/anƟplatelet therapy for IHD</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• <strong>Direct pressure</strong> : apply conƟnuously 10 minutes using haemostaƟc agent (eg (TXA,</div><div class=\"answer-line\">surgicel, gelfoam), avoiding excessive pressure which may result in thrombosis</div><div class=\"answer-line\">• Suture wound : if no success with direct pressure, careful ﬁgure-of-8 or purse string</div><div class=\"answer-line\">to wound</div><div class=\"answer-line\">• Reversal of supratherapeuƟc anƟcoagulaƟon : protamine 1mg for every 100mg</div><div class=\"answer-line\">heparin given during dialysis (if unknown 10-20mg should cover average dose of</div><div class=\"answer-line\">1000-2000 units of heparin)</div><div class=\"answer-line\">• Parenteral agents : IV TXA 1g or DDAVP (0.3mcg/kg over 10 min in consultaƟon with</div><div class=\"answer-line\">vascular surgeon, contraindicaƟon in hypoNa, UAP, CCF)</div><div class=\"answer-line\">• Aggressive management of suspected infecƟon : vancomycin 15mg/kg and</div><div class=\"answer-line\">gentamicin 100mg)</div><div class=\"answer-line\">• Tourniquet or strong manual pressure as LAST RESORT as may result in thrombosis</div><div class=\"answer-line\">and loss of limb (must be clear in their answer that this is a last resort and why)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 4-year-old boy is brought to ED by his mum with ataxia and this :","parts":[{"id":"a","label":"Part A","prompt":"Give (2) potentially life-threatening complications that might arise from the foreign body show in the image. (2 marks) 1. 2."},{"id":"b","label":"Part B","prompt":"List (3) other potential complications. (3 marks) 1. 2. 3."},{"id":"c","label":"Part C","prompt":"Give (4) common differentials of acute ataxia in this age group. (4 marks) 1. 2. 3. 4."},{"id":"d","label":"Part D","prompt":"Outline your steps for safe removal of this foreign body. (3 marks) 1. 2. 3."}],"propPages":["asset:img89e9909f029bd52338"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Respiratory failure</div><div class=\"answer-line\">• Anaphylaxis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Local reacƟon (can be prolonged if head leŌ in situ aŌer removal)</div><div class=\"answer-line\">• Systemic infecƟons : Ricketsia, Q fever (Coxiella burneƫ)</div><div class=\"answer-line\">• Mammalian meat allergy</div><div class=\"answer-line\">• DSCATT = debilitaƟng symptom complexes associated to Ɵcks</div><div class=\"answer-line\">• <em>No evidence of Lyme disease being transmitted by ticks within Australia </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Post infecƟous (acute cerebellar ataxia) – varicella, mycoplasma, EBV, HHV6,</div><div class=\"answer-line\">parvovirus B19, enterovirus, post-immunisaƟon</div><div class=\"answer-line\">• Toxins – anƟhistamines, ETOH and toxic alcohols, anƟcholinergics…</div><div class=\"answer-line\">• Tumours – esp. posterior fossa, neuroblastoma</div><div class=\"answer-line\">• Immune (eg. ADEM)</div><div class=\"answer-line\">• Other (1 of) : metabolic, infecƟons, trauma</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Ensure Ɵck is killed prior to removal by freezing or applicaƟon of permethrin cream</div><div class=\"answer-line\">Grab the Ɵck with forcep Ɵps as close to the skin as possible</div><div class=\"answer-line\">Pull gently to ensure Ɵck remains intact on removal</div><div class=\"answer-line\">Resources :</div><div class=\"answer-line\">htps://www.health.gov.au/sites/default/ﬁles/2022-11/management-of-Ɵck-bites-in-</div><div class=\"answer-line\">australia_0.pdf</div><div class=\"answer-line\">htps://www.rch.org.au/clinicalguide/guideline_index/Common_causes_of_Ataxia/</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 50-year-old female, with a history of pituitary adenoma, presents with sudden severe\nheadache, nausea and vomiting. Vitals are as follows : HR 120 BP 84/60 RR 24 Sats 98% RA Temp 37.8 You are concerned for pituitary apoplexy.","parts":[{"id":"a","label":"Part A","prompt":"List (3) specific clinical features would you seek on examination to support this diagnosis and the underlying cause for each. (3 marks) Clinical feature Underlying cause"},{"id":"b","label":"Part B","prompt":"List (3) possible precipitating factors (3 marks) 1. 2. 3."},{"id":"c","label":"Part C","prompt":"Outline your assessment and management priorities. (6 marks) 1. 2. 3. 4. 5. 6."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>• Ocular palsies esp. CN III – involvement of cavernous sinus</td><td>• Reduced VA, visual ﬁeld defects (bitemporal hemianopia) – opƟc chiasmal</td></tr><tr><td>compression</td><td>• Fever, neck sƟﬀness, photophobia, reduced LOC – meningeal irritaƟon</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• HTN</div><div class=\"answer-line\">• Major surgery (esp CABG)</div><div class=\"answer-line\">• AnƟcoagulaƟon/coagulopathy</div><div class=\"answer-line\">• Head trauma</div><div class=\"answer-line\">• RadiaƟon</div><div class=\"answer-line\">• InfecƟon/sepsis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">• Address haemodynamics</td></tr><tr><td colspan=\"2\">o IVF resuscitaƟon 10-20mL/kg crystalloid Ɵtrated to MAP &gt;65, HR &lt; 100</td></tr><tr><td colspan=\"2\">o <strong>IV hydrocor</strong><strong>Ɵsone 100mg </strong><strong>-200mg stat then q6H </strong></td></tr><tr><td colspan=\"2\">• Seek and treat hypoglycaemia with 50mL 50%D (also seek and treat hypoNa and</td></tr><tr><td colspan=\"2\">hyperK)</td></tr><tr><td colspan=\"2\">• Urgent bloods including FBC/EUC/VBG/LFT/coags/endocrine panel</td></tr><tr><td colspan=\"2\">• Urgent CT/MRI to conﬁrm diagnosis, rule out ddx SAH/cavernous sinus thrombosis</td></tr><tr><td colspan=\"2\">• SupporƟve : analgesia (likely opioid requiring) + anƟemeƟc, 30 deg head up</td></tr><tr><td colspan=\"2\">• Urgent referral to neurosurgery / endocrine for deﬁniƟve management -&gt; ICU</td></tr><tr><td colspan=\"2\"><em>Would accept  </em></td></tr><tr><td>-</td><td><em>LP to rule out SAH/meningitis if any doubt regarding diagnosis </em></td></tr><tr><td>-</td><td><em>IV antibiotics to cover potential meningitis as a diﬀerential </em></td></tr><tr><td>-</td><td><em>Assess and treat potential underlying cause </em></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 33-year-old Indigenous female has been brought into hospital by ambulance following a\nsuspected family violence incident at her home. She is noted to have bruising around her neck and a hoarse voice. Her vital signs are all within normal limits and GCS 15.","parts":[{"id":"a","label":"Part A","prompt":"List (4) neurological clinical features that would be concerning for a serious underlying injury in this setting (4 marks) 1. 2. 3. 4."},{"id":"b","label":"Part B","prompt":"Aside from Aboriginal and Torres Strait Islander people, list (4) other groups which are at increased risk of family violence. (4 marks) 1. 2. 3. 4. The patient is reluctant to talk to medical staff about the incident."},{"id":"c","label":"Part C","prompt":"Outline how you might increase her likelihood of engagement. (2 marks) 1. 2. One of the registrars involved in this patient’s care was noted to be visibly upset during their shift."},{"id":"d","label":"Part D","prompt":"Outline how you could support the registrar. (2 marks) 1. 2."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Seizures</div><div class=\"answer-line\">• New focal neurological deficits</div><div class=\"answer-line\">• Severe headache</div><div class=\"answer-line\">• Near or complete loss of consciousness</div><div class=\"answer-line\">• Urinary or faecal incontinence</div><div class=\"answer-line\">• Altered mental status eg amnesia, confusion, restlessness agitation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Women in pregnancy and early motherhood</div><div class=\"answer-line\">• Children</div><div class=\"answer-line\">• People living in rural and remote areas</div><div class=\"answer-line\">• Older women</div><div class=\"answer-line\">• Culturally and linguistically diverse people, migrants, refugees</div><div class=\"answer-line\">• People with disability or mental illness</div><div class=\"answer-line\">• LGBTQI+ people</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Involve Aboriginal health workers / liaison officer where available</div><div class=\"answer-line\">• Consider use of interpreters if they have another preferred language</div><div class=\"answer-line\">• Involve social worker or other available psychosocial workers (such as violence,</div><div class=\"answer-line\">abuse and neglect or sexual assault services staff)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Encourage them to talk with a trusted colleague / mentor</div><div class=\"answer-line\">• Take part in a structured debrief</div><div class=\"answer-line\">• Counselling and support services through the Employee Assistance Program</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 22-year-old Ubereats delivery man is brought in by retrieval to your tertiary emergency\nhaving been run over by a bus. He is complaining of severe pelvis and lower back pain. He was wearing a helmet and has no clinical evidence of a head injury. He has been persistently tachycardic and hypotensive prehospital.\nHis observations on arrival to resus are: Temp 36, HR 122, BP 70/50, RR 22, Sats 95% RA, GCS\n14/15. A full trauma call has been placed. A mobile pelvis Xray is performed and shown below:","parts":[{"id":"a","label":"Part A","prompt":"List (2) pertinent positive findings shown on this Xray. (2 marks) 1. 2."},{"id":"b","label":"Part B","prompt":"Complete the table below, giving the major radiological findings of each category of the Young and Burgess/Resnick classification of pelvic fractures. (3 marks) Category Major radiological findings Lateral compression AP compression Vertical sheer"},{"id":"c","label":"Part C","prompt":"How would you classify this patient’s injury? (1 mark)"},{"id":"d","label":"Part D","prompt":"State (8) actions you will take to optimise the patient’s haemodynamic status. Include doses/endpoints where relevant. (8 marks) 1. 2. 3. 4. 5. 6. 7. 8."},{"id":"e","label":"Part E","prompt":"List (4) potential IMMEDIATE complications of this injury. (4 marks) 1. 2. 3. 4."}],"propPages":["asset:img0f3bc86ffd0211c440"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Pubic symphysis diastasis (&gt;2.5cm by visual estimation)</div><div class=\"answer-line\">• Left SI joint diastasis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Oblique pubic rami fracture, iliac crest fracture</div><div class=\"answer-line\"><strong>AP compression </strong></div><div class=\"answer-line\">Symphyseal diastasis &gt; or &lt; 2.5cm +/- posterior ligament</div><div class=\"answer-line\">disruption</div><div class=\"answer-line\"><strong>Vertical sheer </strong></div><div class=\"answer-line\">Ligament or bony disruption of hemipelvis at pubic rami,</div><div class=\"answer-line\">posterior ligament</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">APC Type III (or II)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Ensure pelvic binder applied correctly</strong> over greater trochanters to reduce pelvic</td></tr><tr><td colspan=\"2\">volume and tamponade haemorrhage</td></tr><tr><td><strong>2. </strong></td><td>Ensure multiple high flow IV access ie rapid infuser, 16G IVC</td></tr><tr><td><strong>3. </strong></td><td><strong>TXA 1g bolus then infusion over 8 hours </strong></td></tr><tr><td><strong>4. </strong></td><td><strong>Commence warmed O group blood whilst activating</strong> <strong>massive transfusion </strong></td></tr><tr><td colspan=\"2\"><strong>protocol</strong> ensuring 1:1:1 replacement of blood products as guided by TEG/ROTEM if</td></tr><tr><td colspan=\"2\">available (or FBC/coags/fibrinogen/D-dimer/lactate)</td></tr><tr><td><strong>5. </strong></td><td><strong>Controlled hypotension</strong> targeting SBP 90mmg Hg and end-organ perfusion</td></tr><tr><td><strong>6. </strong></td><td><strong>Maintain normothermia</strong>, minimal handling/rolling to prevent further disruption to</td></tr><tr><td colspan=\"2\">blood vessels/clot</td></tr><tr><td><strong>7. </strong></td><td>Identify other sources of bleeding : FAST, CTA panscan<strong> </strong></td></tr><tr><td><strong>8. </strong></td><td><strong>Definitive haemorrhage control </strong>with urgent referral to orthopaedics /</td></tr><tr><td colspan=\"2\">interventional radiology</td></tr><tr><td colspan=\"2\"><em>*Need bold points to get full marks*</em><em> </em></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">• Major haemorrhage – <em>major cause of death from fractured pelvis, can lose up to 6 </em></div><div class=\"answer-line\"><em>litres in complex fractures  </em></div><div class=\"answer-line\">• Bladder injury</div><div class=\"answer-line\">• Urethral injury</div><div class=\"answer-line\">• Rectal injuries</div><div class=\"answer-line\">• Nerve injuries – lumbosacral plexus at risk, S1/2 nerve roots in posterior element</div><div class=\"answer-line\">fractures</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 3-year-old girl presents to your rural ED with 2 days of sore throat, diarrhoea, fevers and increasing work of breathing. She has no significant past medical history, no regular medications and her vaccinations are up to date. She appears lethargic and her initial\n• bservations are as follows:\n\nRR\n\nSats\n91% RA\n\nHR\n190 CRT 5 seconds\n\nTemp 38.5 ̊C\nShe undergoes a mobile chest X-ray in resus which is shown below :","parts":[{"id":"a","label":"Part A","prompt":"State the MOST LIKELY diagnosis and 2 causative agents (1/2 mark each). (2 marks) Most likely diagnosis\nCause 1\nCause 2"},{"id":"b","label":"Part B","prompt":"List (3) differential diagnoses for the X-ray appearance. (3 marks) 1. 2. 3."},{"id":"c","label":"Part C","prompt":"State and justify (6) investigations you would perform in this child. (6 marks) Investigation Justification"},{"id":"d","label":"Part D","prompt":"List (2) indications for chest drain insertion in a child with this clinical presentation. (2 marks) 1. 2."},{"id":"e","label":"Part E","prompt":"Outline (5) INITIAL management priorities for this child. (5 marks) 1. 2. 3. 4. 5."}],"propPages":["asset:imge3843ef6dd8ab9e7a6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Most likely parapneumonic eﬀusion secondary to Strep pneumonia, GAS (Strep</div><div class=\"answer-line\">pyogenes or Staph aureus</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Empyema</div><div class=\"answer-line\">• Atypical infecƟon (TB, mycoplasma)</div><div class=\"answer-line\">• Malignant pleural eﬀusion</div><div class=\"answer-line\">• CCF</div><div class=\"answer-line\">• SerosiƟs from rheumatologic cause</div><div class=\"answer-line\">• FB/collapse/consolidaƟon less likely as appearances more in keeping in eﬀusion</div><div class=\"answer-line\">(tracheal deviaƟon to contralateral side, rib spreading)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Bedside</div><div class=\"answer-line\">• Lung ultrasound - delineate consolidaƟon vs eﬀusion, simple vs loculated eﬀusion for</div><div class=\"answer-line\">drainage</div><div class=\"answer-line\">• Cardiac ultrasound - exclude pericardial eﬀusion as source of shock</div><div class=\"answer-line\">• VBG - deﬁne acid/base status, exclude hypoglycaemia and guide resuscitaƟon</div><div class=\"answer-line\">• ECG - exclude SVT as cause of tachycardia</div><div class=\"answer-line\">Laboratory</div><div class=\"answer-line\">• FBC - assess for elevated WCC in sepsis</div><div class=\"answer-line\">• EUC - idenƟfy concurrent renal failure, electrolyte imbalance from diarrhoea</div><div class=\"answer-line\">• Blood cultures - guide further anƟbioƟc therapy</div><div class=\"answer-line\">• Bacterial Throat swab - idenƟfy causaƟve organism to guide therapy, esp iGAS (beter</div><div class=\"answer-line\">candidates)</div><div class=\"answer-line\">• Viral respiratory panel - idenƟfy viral causes for consideraƟon of disease modifying</div><div class=\"answer-line\">drugs eg inﬂuenza, COVID</div><div class=\"answer-line\">• Pneumococcal PCR (would this be available in a rural centre?)</div><div class=\"answer-line\">• CRP (1/2 mark) – to guide disease trajectory</div><div class=\"answer-line\">Radiology - NO MARKS FOR CT (not indicated in this age group or process)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Complicated eﬀusion</div><div class=\"answer-line\">• Severe respiratory distress</div><div class=\"answer-line\">• SepƟc shock (drain may be required for source control)</div><div class=\"answer-line\">• Ongoing fever and/or respiratory distress aŌer 48 hours of IV anƟbioƟcs</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">i. High Flow O2 - 2L/kg Ɵtrate to SPO2 &gt;94% and improved WOB</div><div class=\"answer-line\">ii. CPAP  - Possibly appropriate as iniƟal therapy but HFO2 more appropriate</div><div class=\"answer-line\">iii. Low ﬂow O2 (1/2 mark)</div><div class=\"answer-line\">1. 2-4L/min O2 via NP aiming SATS &gt;94%</div><div class=\"answer-line\">2. With RR of 60 this child needs more respiratory support</div><div class=\"answer-line\">IntubaƟon and venƟlaƟon not appropriate as iniƟal management</div><div class=\"answer-line\"><strong>Treat shock : </strong>NS 10-20ml/kg bolus repeat q5-10 minutes aim for CRT&lt;3s, max</div><div class=\"answer-line\">60ml/kg then start vasopressor therapy<strong> </strong></div><div class=\"answer-line\"><strong>Early an</strong><strong>ƟbioƟc therapy</strong><strong> </strong></div><div class=\"answer-line\">Cefotaxime 50mg/kg IV bolus OR<strong> </strong>CeŌriaxone 50mg/kg IV OR<strong> </strong>Ampicillin 50mg/kg IV</div><div class=\"answer-line\">AND<strong> </strong>Gentamicin 7mg/kg IV OR<strong> </strong>Clindamycin 15mg/kg IV (iGAS coverage)</div><div class=\"answer-line\"><strong>Suppor</strong><strong>Ɵve : </strong>anƟpyreƟcs eg paracetamol 15mg/kg PO<strong>,  </strong>ibuprofen 10mg/kg PO  –</div><div class=\"answer-line\">cauƟon as may have AKI, seek and treat hypoglycaemia</div><div class=\"answer-line\"><strong>Disposi</strong><strong>Ɵon :</strong><strong> early organisa</strong><strong>Ɵon of retrieval to terƟary paediatric centre</strong><strong> </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 46-year-old female is brought in by partner. He reports she has been lethargic with\ndecreased appetite over the last few days. On consultation she is vague and drowsy. Looking back through her notes she has a previously documented alcohol use disorder. She is known to a liver clinic and a recent endoscopy confirmed that the patient has oesophageal varices.\nCurrent observations GCS 14/15, HR 85, BP 100/60 RR 18 Sats 98% RA.","parts":[{"id":"a","label":"Part A","prompt":"List (8) signs of chronic liver disease you would seek on clinical examination. (4 marks) 1. 2. 3. 4. 5. 6. 7. 8. You suspect hepatic encephalopathy as the cause of her confusion."},{"id":"b","label":"Part B","prompt":"Give the most important therapy in management of acute hepatic encephalopathy including dose. (1 mark) Whilst in the ED she has several large volume melaena episodes and becomes hypotensive with the following observations HR 110, BP 60/34, Sats 97%, RR 17."},{"id":"c","label":"Part C","prompt":"What is your immediate management of this patient? (5 marks) 1. 2. 3. 4. 5."},{"id":"d","label":"Part D","prompt":"Give (2) commonly used medications which have been shown to not be of benefit in variceal bleeding in recent trials (2 marks) 1. 2."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Jaundice</div><div class=\"answer-line\">• GynaecomasƟa</div><div class=\"answer-line\">• Leuconychia</div><div class=\"answer-line\">• Palmar erythema</div><div class=\"answer-line\">• Clubbing</div><div class=\"answer-line\">• Spider naevi</div><div class=\"answer-line\">• Hepatosplenomegaly</div><div class=\"answer-line\">• Caput medusa</div><div class=\"answer-line\">• TesƟcular atrophy</div><div class=\"answer-line\">• Loss of body hair</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Lactulose 20-30 ml PO ( or via NG)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Haemodynamic resuscitaƟon- 2 x IVC, acƟvate MTP ( PRC:FFP:plts at 1:1:1) aiming for</div><div class=\"answer-line\">end organ perfusion eg normal mentaƟon (tricky as encephalopathic), SBP&gt;</div><div class=\"answer-line\">80mmHg, UO 0.5mL/kg/hr)</div><div class=\"answer-line\">• Correct coagulopathy: vit K 10 mg IV, plts if not giving mtp</div><div class=\"answer-line\">• Treat precipitant: IV ceŌriaxone 1-2 g, asciƟc tap to isolate pathogen if suspect SBP</div><div class=\"answer-line\">• Reduced splanchnic blood ﬂow : octreoƟde 50 mcg IV bolus or terlipressin 1.7mg IV</div><div class=\"answer-line\">• DisposiƟon: liaise with gastroenterology to organise urgent endoscopy for banding/</div><div class=\"answer-line\">cryotherapy</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• TXA (HALT-IT trial)</div><div class=\"answer-line\">• PPI</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 34-year-old cyclist presents to ED aŌer being struck by a car. He complains of severe right- sided pleuritic chest pain despite 20mg IV morphine. Vital signs are: HR 105, BP 140/80, RR 22, SpO2 94% on 2L NP, GCS 15. A slice from his CT chest is shown below :","parts":[{"id":"a","label":"Part A","prompt":"List (2) positive findings on this CT and (1) relevant negative finding. (3 marks) +ve +ve -ve 3D recon of the patient’s CT is shown below : The patient still has significant pain despite a further 20mg IV morphine."},{"id":"b","label":"Part B","prompt":"Complete the table below, outlining (3) strategies for providing ongoing analgesia to this patient. Answers must include details of dosing and (1) pro and (1) con for each method (9 marks). Strategy Medication Dose Pro Con"}],"propPages":["asset:imgad30ac8b1865f1adcf","asset:imgaa1dae3d07e3b85801"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Right posterior rib fracture(s)</div><div class=\"answer-line\">• Subcutaneous emphysema and Ɵny right-sided pneumothorax</div><div class=\"answer-line\">• Small right-sided haemothorax</div><div class=\"answer-line\"><strong>Nega</strong><strong>Ɵve ﬁnding</strong><strong> </strong></div><div class=\"answer-line\">• No large pneumothorax requiring drainage</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Pros </strong></td><td><strong>Cons </strong></td></tr><tr><td>Opiate PCA</td><td>Fentanyl 20mcg Well tolerated, patient Requires cooperative</td></tr><tr><td>bolus, 5 minute</td><td>is in control, fewer patient</td></tr><tr><td>lockout</td><td>delays to analgesia</td></tr><tr><td>Nerve block -e.g.</td><td>Ropivacaine 20- Opiate-sparing effect, Serratus block may not</td></tr><tr><td>serratus plane block</td><td>40mls of 0.375% provides long-lasting work with posterior rib</td></tr><tr><td>/ erector spinae</td><td>analgesia fractures. Invasive,</td></tr><tr><td>block</td><td>potential risk of</td></tr><tr><td>pneumothorax</td><td></td></tr><tr><td>Ketamine bolus /</td><td>Bolus 10-20mg, Less respiratory Dysphoria, hallucinations,</td></tr><tr><td>infusion</td><td>infusion 0.1- depression than opiates agitation,</td></tr><tr><td>0.2mg/kg/hr</td><td>sympathomimetic effects</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"You are working in a tertiary ED on a busy Saturday evening, when a 78-year-old man arrives in your resus room by ambulance with 1-hour of central chest pain which started whilst rock’n’roll dancing at his daughter’s wedding. He has had one vomit and has ongoing pain.\nCDA have given 300mg aspirin which he has kept down.\nHe is alert but slightly diaphoretic with a BP of 95/60.\nA 12-lead ECG is performed and shown below :","parts":[{"id":"a","label":"Part A","prompt":"Give (4) important findings on the ECG. (4 marks) 1. 2. 3. 4."},{"id":"b","label":"Part B","prompt":"State your interpretation. (2 marks)"},{"id":"c","label":"Part C","prompt":"Would you consider trialling atropine for this patient? Justify your answer. (1 mark)"},{"id":"d","label":"Part D","prompt":"State your (5) immediate management priorities. (5 marks) 1. 2. 3. 4. 5."}],"propPages":["asset:imgbc5a41b6e0278368e0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• &gt;2mm inferior ST elevaƟon with reciprocal change I, avL, STE III &gt; II</div><div class=\"answer-line\">• Downsloping ST depression V1-V3</div><div class=\"answer-line\">• Atrial ﬂuter with complete HB (accept high degree AVB)</div><div class=\"answer-line\">• JuncƟonal escape rhythm 42/min</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Inferior STEMI with posterior extension, likely RV and AVN involvement from RCA/LCx</div><div class=\"answer-line\">occlusion – needs urgent revascularisaƟon</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Yes – might increase rate of juncƟonal pacemaker</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Urgent discussion with intervenƟonal cardiologist for cath lab acƟvaƟon</div><div class=\"answer-line\">• AnƟplatelet/anƟcoagulaƟon : Ɵcagrelor 180mg or clopidogrel 600mg loading, IV</div><div class=\"answer-line\">heparin 5000 unit bolus followed by infusion</div><div class=\"answer-line\">• OpƟmise preload : 500mL IV crystalloid boluses Ɵtrated to MAP &gt; 65mmHg,</div><div class=\"answer-line\"><strong>avoid nitrates </strong></div><div class=\"answer-line\">• Address bradycardia : ensure pacing pads placed, intervene only if remains</div><div class=\"answer-line\">hypotensive despite ﬂuid boluses, trial atropine up to 2mg then commence low-</div><div class=\"answer-line\">dose adrenaline infusion</div><div class=\"answer-line\">• SupporƟve : 25mcg boluses of IV fentanyl Ɵtrated to eﬀect, IV anƟemeƟc 4-8mg</div><div class=\"answer-line\">ondansetron</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 1-year-old presents with facial burns from gas oven explosion.\nHe has a hoarse voice, stridor, 92% saturations in room air and 40 % TBSA partial and full thickness burns. A clinical photo is shown below :","parts":[{"id":"a","label":"Part A","prompt":"Describe your airway concerns. (4 marks) 1. 2. 3. 4."},{"id":"b","label":"Part B","prompt":"Outline your airway management in sequential order. (4 marks) 1. 2. 3. 4."},{"id":"c","label":"Part C","prompt":"Other than airway, state your other acute management. (4 marks) 1. 2. 3. 4."}],"propPages":["asset:img0fa0592500b52766e9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Ques</strong><strong>Ɵon </strong><strong>13 (12 marks) </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">A 1-year-old presents with facial burns from gas oven explosion.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">htps://vimeo.com/932005666/7acf5287de?share=copy</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 38-year-old woman presents to your ED with several weeks of lethargy.\nVitals are as follows : T 36.5 HR 95 BP 120/70 RR 20 Sats 99%RA Her FBC is shown below :\n\nHb\n70 g/L\nMCV 72\n\nWCC\n7.4 Plt 380","parts":[{"id":"a","label":"Part A","prompt":"List (6) potential causes of iron deficiency anaemia (IDA) in this patient. (6 marks) 1. 2. 3. 4. 5. 6."},{"id":"b","label":"Part B","prompt":"Complete the table below with findings that would support a diagnosis of IDA. (3 marks) Test Finding supportive of IDA S. Ferritin % Transferrin Red cell distribution width (RDW) Total iron binding capacity (TIBC) Reticulocyte count Blood film"},{"id":"c","label":"Part C","prompt":"State (3) seƫngs in which the use of parenteral iron may be preferable to oral iron replacement. (3 marks) 1. 2. 3."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Blood loss : <strong>menorrhagia</strong>, <strong>chronic occult</strong> (eg PUD, malignancy, haemorrhoids,</div><div class=\"answer-line\">vascular ectasia – accept max 2), exercise-induced haemolysis, frequent phlebotomy</div><div class=\"answer-line\">• Increased iron requirements :<strong> </strong>pregnancy (and lactaƟon)</div><div class=\"answer-line\">• Decreased iron absorpƟon  : gastrectomy, <strong>malabsorp</strong><strong>Ɵon syndromes</strong><strong> </strong>(coeliac,</div><div class=\"answer-line\">atrophic gastriƟs, <em>H pylori </em>infecƟon, short bowel syndrome, bariatric surgery – accept</div><div class=\"answer-line\">max 2)</div><div class=\"answer-line\">• Iron-restricted diet eg. vegetarian/vegan with no supplementaƟon</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Low or normal</div><div class=\"answer-line\"><strong>% Transferrin </strong></div><div class=\"answer-line\">&lt;20%</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Poor tolerance of GI side eﬀects (consƟpaƟon, metallic taste, nausea, epigastric pain,</div><div class=\"answer-line\">ﬂatulence, diarrhoea, itching) -&gt; poor compliance</div><div class=\"answer-line\">Preference to replete iron stores in 1-2 visits rather than over the course of several</div><div class=\"answer-line\">months</div><div class=\"answer-line\">Ongoing blood loss that exceeds the capacity of oral iron to meet needs (eg heavy</div><div class=\"answer-line\">uterine bleeding, telangiectasias)</div><div class=\"answer-line\">Anatomic or physiologic condiƟon that interferes with oral iron absorpƟon</div><div class=\"answer-line\">CoexisƟng inﬂammatory state that interferes with iron homeostasis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 12-month-old girl is brought into your Emergency Department with a painful leŌ ear. She\nhas been seen to pull at her leŌ ear for the last 4 days and mum has been providing her with paracetamol and ibuprofen. She does not have any pre-existing medical conditions or regular medications.\nHer vital signs are: HR 160/min RR 26/min Temp 38.4\nA clinical photo of the patient is provided below :","parts":[{"id":"a","label":"Part A","prompt":"State the most likely diagnosis and (2) common causative organisms (3 marks) Most likely diagnosis\nOrganism 1\nOrganism 2"},{"id":"b","label":"Part B","prompt":"List (5) clinical features associated with this condition (5 marks) 1. 2. 3. 4. 5."},{"id":"c","label":"Part C","prompt":"State your immediate management steps, including drug doses. (4 marks) 1. 2. 3. 4."}],"propPages":["asset:imgc5d9cb252e5cdb96f9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Acute mastoidiƟs</div><div class=\"answer-line\">• Group A streptococci or Strep Pneumoniae or Staph aureus</div><div class=\"answer-line\">• <em>Pseudomonas does not score a mark as this is a common EAC ﬂora rather than a </em></div><div class=\"answer-line\"><em>common cause for mastoiditis (eTG) </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• recent acute oƟƟs media</div><div class=\"answer-line\">• otorrhoea</div><div class=\"answer-line\">• ear pain</div><div class=\"answer-line\">• EAC oedema, signs of AOM</div><div class=\"answer-line\">• complicated mastoidiƟs</div><div class=\"answer-line\">o displacement of the ear downward, outward, and forward (protrusion of</div><div class=\"answer-line\">auricle)</div><div class=\"answer-line\">o mastoid erythema and ﬂuctuance</div><div class=\"answer-line\">o facial nerve palsy</div><div class=\"answer-line\">No mark for answers referring to chronic nonsuppuraƟve complicaƟons such as TM</div><div class=\"answer-line\">atelectasis or cholesteatoma</div><div class=\"answer-line\">(Dunn and RCH Guidelines)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• IV anƟbioƟcs CeŌriaxone 50mg/kg or 500mg daily (esƟmated weight 10kg at 12</div><div class=\"answer-line\">months) OR Cefotaxime 50mg (same as cef) Q8H</div><div class=\"answer-line\">o Oral anƟbioƟcs are not acceptable in this instance. Guidelines suggest</div><div class=\"answer-line\">minimum 5 days of intravenous therapy.</div><div class=\"answer-line\">• Analgesia – appropriate dose and route</div><div class=\"answer-line\">o No mark for auralgan as likely to have perforated TM with OME</div><div class=\"answer-line\">• Admission under ENT – may require surgical intervenƟon eg. myringotomy,</div><div class=\"answer-line\">mastoidectomy</div><div class=\"answer-line\">• Keep NBM with maintenance ﬂuids unƟl surgical review/plan</div><div class=\"answer-line\">• Explain diagnosis and management plan to parents</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 38-year-old lady, G1P0 at 34/40 gestation, is brought in by ambulance to your tertiary\nemergency department aŌer a witnessed cardiac arrest.","parts":[{"id":"a","label":"Part A","prompt":"List (4) causes of cardiac arrest you need to specifically consider in the pregnant patient. (4 marks) 1. 2. 3. 4. You and your team continue the ALS protocol."},{"id":"b","label":"Part B","prompt":"In the table below, list (4) issues which complicate the management of the arrested pregnant patient and provide a solution for each. (4 marks) Issue Solution"},{"id":"c","label":"Part C","prompt":"What are the indications for a resuscitative hysterotomy? (2 mark) 1. 2."},{"id":"d","label":"Part D","prompt":"State (2) benefits of the procedure. (2 marks) 1. 2."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• AmnioƟc ﬂuid embolism</div><div class=\"answer-line\">• PE</div><div class=\"answer-line\">• Hypertensive disorder of pregnancy (with ensuing cardiac failure)</div><div class=\"answer-line\">• Maternal cardiac disease – peripartum cardiomyopathy, dysrhythmia, aorƟc</div><div class=\"answer-line\">dissecƟon</div><div class=\"answer-line\">• Seizures (with ensuing hypoxia and arrest)</div><div class=\"answer-line\">• Haemorrhage from uterine rupture/placental abrupƟon/praevia, liver rupture or DIC</div><div class=\"answer-line\">• Sepsis</div><div class=\"answer-line\">• Poisoning and self-harm</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Issue</th><th>Management</th></tr></thead><tbody><tr><td>Difficult airway <strong> </strong></td><td>Most experienced operator, careful intubation with</td></tr><tr><td>smaller ETT</td><td></td></tr><tr><td>Limited oxygen reserve</td><td>Early ventilatory support with FIO2 1.0</td></tr><tr><td><strong>Aortocaval compression</strong></td><td><strong>Continuous left lateral uterine displacement </strong></td></tr><tr><td>Difficulty placing defib pads due to</td><td>Biaxillary or AP pad placement</td></tr><tr><td>enlarged breast tissue</td><td></td></tr><tr><td>Two patients</td><td>Early notification of obstetric and paediatric teams</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Cardiac arrest in paƟent &gt;20 weeks gestaƟon (fundus above umbilicus)</div><div class=\"answer-line\">• Maternal cardiac arrest without ROSC within 4 minutes (in reality up to 30 minutes)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Reduces aortocaval compression, improves preload</div><div class=\"answer-line\">• Improves maternal pulmonary mechanics</div><div class=\"answer-line\">• Reduces maternal oxygen demand</div><div class=\"answer-line\">• In the presence of truly unsalvageable maternal pathology, oﬀers a chance for foetal</div><div class=\"answer-line\">survival if &gt;24/40</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 25-year-old man with a history of depression and anxiety is BIBA, 3 hours aŌer taking an\ndeliberate overdose of 4g Efexor XL.\nHe is alert with following vitals : HR 90 BP 120/80 RR 20 Sats 98%RA T 36.8","parts":[{"id":"a","label":"Part A","prompt":"What is your risk assessment? (1 mark)"},{"id":"b","label":"Part B","prompt":"What is the role of decontamination for this presentation? (1 mark)"},{"id":"c","label":"Part C","prompt":"List (5) examination findings of the Hunter Serotonin Syndrome Criteria you would seek (you do not have to cite the specific criteria). (5 marks) 1. 2. 3. 4. 5."},{"id":"d","label":"Part D","prompt":"Outline (3) features which would distinguish Neuroleptic Malignant Syndrome from Serotonin Syndrome. (3 marks) 1. 2. 3. The patient somehow absconds from your department and is brought back several hours later having been found unconscious by his partner at home. He is now manifesting features of severe Serotonin Syndrome."},{"id":"e","label":"Part E","prompt":"Give (3) potential life threats for this poisoning and the appropriate resuscitative interventions for each. (6 marks) Life threat Intervention(s)"},{"id":"f","label":"Part F","prompt":"State (2) agents that can be used in the specific management of mild-moderate Serotonin Syndrome. (2 marks) 1. 2."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">PaƟent has taken &gt;2g - is at risk of seizures and serotonin syndrome</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Signiﬁcant OD of an extended release preparaƟon, so would oﬀer acƟvated charcoal up</div><div class=\"answer-line\">to 4 hours as long as alert, cooperaƟve and maintaining airway</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">He is alert with following vitals :  HR 90  BP 120/80  RR 20  Sats 98%RA  T 36.8</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• More gradual onset (days-weeks)</div><div class=\"answer-line\">• Caused by prolonged exposure to anƟpsychoƟcs OR cessaƟon of dopaminergic</div><div class=\"answer-line\">agents</div><div class=\"answer-line\">• Hyporeﬂexia and lead-pipe rigidity</div><div class=\"answer-line\">• Normal pupils (no mydriasis)</div><div class=\"answer-line\">• Can be accompanied by rhabdomyolysis -&gt; AKI</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Seizures</td><td>1st line : benzos (eg. midazolam/diazepam 5-10mg IV</td></tr><tr><td>q5min)</td><td></td></tr><tr><td>2nd line : phenobarb or keppra 20mg/kg</td><td></td></tr><tr><td>NOT phenytoin</td><td></td></tr><tr><td>Intubation and ventilation</td><td></td></tr><tr><td>Hyperthermia</td><td>Cool IV fluids</td></tr><tr><td>Active cooling methods eg. ice packs to groin/axillae</td><td></td></tr><tr><td>Consider intubation, ventilation and paralysis if T &gt;</td><td></td></tr><tr><td>39.5°C</td><td></td></tr><tr><td>Chest wall rigidity resulting in</td><td>Intubation and ventilation</td></tr><tr><td>T2 respiratory failure</td><td></td></tr><tr><td>Also accept : Profound HTN – benzodiazepine or hypotension in seƫng of</td><td></td></tr><tr><td>fever/autonomic instability.  Cardiac dysrhythmia more likely with massive OD &gt;8g so</td><td></td></tr><tr><td>should qualify this.  Coma not generally a feature of SNRI</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">g) Diazepam 5-20mg can repeat at 30min</div><div class=\"answer-line\">Cyproheptadine 12mg PO then 8mg q8h for 24h</div><div class=\"answer-line\">Chlorpromazine 25mg in 1L NS over 30 minutes</div><div class=\"answer-line\">Olanzapine 10mg SL</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 25-year-old trans female is BIBA with reduced LOC on a background of T1DM with multiple\nadmissions due to medication noncompliance. She vomited several times en route. Initial obs : HR 130, BP 82/40, RR 36, Sats 95% 10L/min NRB GCS E3V3M5 = 11 T37.4 A VBG is performed and shown below :\n\npH\n6.8\n\npCO2\n17 mmHg\n\nHCO3\n3 mmol/L\n\nNa\n124 mmol/L\n\nK\n8.0 mmol/L\n\nCl\n88 mmol/L\n\nLactate\n5 mmol/L\n\nGlucose\n> 40mmol","parts":[{"id":"a","label":"Part A","prompt":"Give (4) relevant equations and an interpretation for each (8 marks) Equation Interpretation"},{"id":"b","label":"Part B","prompt":"State your treatment priorities for this patient in the first hour of their ED stay including drug doses/routes where relevant. (5 marks) 1. 2. 3. 4. 5."},{"id":"c","label":"Part C","prompt":"List (5) medical/psychosocial risks factors that have been shown to affect trans patients at higher rates than the general population. (5 marks) 1. 2. 3. 4. 5."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>AG = Na – (HCO3 + Cl)</td><td>Profound HAGMA likely secondary to DKA and</td></tr><tr><td>= 124 – (3 +88)</td><td>elevated lactate from hypoperfusion</td></tr><tr><td>= 33</td><td></td></tr><tr><td>Delta gap = ΔAG – ΔHCO3</td><td>Pure HAGMA</td></tr><tr><td>= (33-12) – (24-3) = 21- 21 = 0</td><td></td></tr><tr><td>Expected CO2 = 1.5 x HCO3 + 8 = 12.5</td><td>Actual CO2 17 – attempted respiratory</td></tr><tr><td>compensation, concomitant respiratory acidosis</td><td></td></tr><tr><td>Corrected K = K - 0.6 x each 0.1 drop in pH</td><td>Life-threatening hyperK secondary to</td></tr><tr><td>= 8.0 – 0.6 (7.4-6.8) x 10 = 4.4</td><td>extracellular shift from acidosis</td></tr><tr><td>Corrected Na = Na + gluc-10/3</td><td>Dilutional hypoNa</td></tr><tr><td>= 124 + 10 = 134 (est gluc)</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• <strong>Restore perfusion </strong>: IV crystalloid 1L over 1hr and repeat +/- vasopressor if</div><div class=\"answer-line\">inadequate response</div><div class=\"answer-line\">• <strong>Treat hyperkalaemia</strong>: Should respond to ﬂuid resus but is signiﬁcant in this paƟent</div><div class=\"answer-line\">therefore give 10mmol 10mL IV calcium gluconate  + 10 units IV actrapid / novorapid</div><div class=\"answer-line\">• <strong>Treat ketoacidosis</strong>:  Fast acƟng insulin infusion 0.1U/kg/hr (actrapid / novorapid)</div><div class=\"answer-line\">• Respiratory support : HFNC FiO2 Ɵtrated to Sats &gt; 92% increasing ﬂow rate as high as</div><div class=\"answer-line\">paƟent can tolerate <em>(reduces deadspace and WOB) </em></div><div class=\"answer-line\">• Treat vomiƟng : Ondansetron 4-8mg IV / metoclopramide 10mg IV</div><div class=\"answer-line\"><em><strong>NO MARKS FOR INTUBATION unless appropriate indication stated, want to avoid this </strong></em></div><div class=\"answer-line\"><em><strong>where possible – mental status should improve over time with resuscitation </strong></em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Suicide</div><div class=\"answer-line\">• HIV infecƟon</div><div class=\"answer-line\">• Drug use</div><div class=\"answer-line\">• Sexual assault</div><div class=\"answer-line\">• DomesƟc violence</div><div class=\"answer-line\">• Sex work</div><div class=\"answer-line\">• Likelihood of living in extreme poverty</div><div class=\"answer-line\">• Twice as likely to be unemployed</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
